export interface WorldState {
  entities: Record<string, string>;
}

const FEN = "Fen";
const NIM = "nim";
const PEX = "pex";

function copyState(state: WorldState): WorldState {
  return { entities: { ...state.entities } };
}

function isFenToPexOperation(operationDisplayName: string): boolean {
  const operation = operationDisplayName.toLowerCase();
  return (
    (operation.includes("fen") && operation.includes("pex")) ||
    operation === "advancefen" ||
    operation === "activatefen"
  );
}

export const protocol: WorldProtocol = {
  reset(): WorldState {
    return { entities: { [FEN]: NIM } };
  },

  applyOperation(state, operationDisplayName) {
    const fenState = state.entities[FEN];

    if (operationDisplayName === "resetFen") {
      if (fenState !== PEX) {
        return {
          success: false,
          error: `resetFen requires ${FEN} to be in state ${PEX}`,
        };
      }

      const newState = copyState(state);
      newState.entities[FEN] = NIM;
      return { success: true, newState };
    }

    if (isFenToPexOperation(operationDisplayName)) {
      if (fenState !== NIM) {
        return {
          success: false,
          error: `The operation requires ${FEN} to be in state ${NIM}`,
        };
      }

      const newState = copyState(state);
      newState.entities[FEN] = PEX;
      return { success: true, newState };
    }

    return {
      success: false,
      error: `Unknown operation: ${operationDisplayName}`,
    };
  },

  getEntityState(state, entityDisplayName) {
    return state.entities[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state) {
    return { ...state.entities };
  },
};
"}],"workingNote":"Added resetFen with an immutable pex-to-nim transition and a precondition failure for other Fen states. The protocol surface remains reset, applyOperation, getEntityState, and toAbstractSnapshot; snapshots expose entity display names and unknown entities return a string."}

